{
  "packet_id": "H6-T03-2",
  "claim_id": "C006",
  "status": "SUPPORTED",
  "claim": {
    "component_id": "C006.component",
    "value": "Delegated-authority forms cannot be assumed to satisfy the approval rule merely because they are available as approval-related records.",
    "scope": "Potential use of delegated-authority forms; their rule satisfaction remains to be established.",
    "provenance": {
      "refs": [
        {
          "source_id": "P004",
          "role": "SUPPORT"
        }
      ],
      "support_status": "SUFFICIENT",
      "rationale": "P004 explicitly disallows assuming that delegated-authority forms satisfy the rule."
    }
  },
  "signal_basis": {
    "component_id": "C006.signal_basis",
    "value": "Examine the applicable approval requirements and distinguish delegated authority within its terms from approval of a particular order; cross-check records for the order, relevant authority, approval scope and documented occurrence before placement.",
    "scope": "Assessment of whether a delegated-authority form contributes evidence satisfying the particular order's approval requirements.",
    "provenance": {
      "refs": [
        {
          "source_id": "P003",
          "role": "SUPPORT"
        },
        {
          "source_id": "P008",
          "role": "SUPPORT"
        },
        {
          "source_id": "P015",
          "role": "SUPPORT"
        }
      ],
      "support_status": "SUFFICIENT",
      "rationale": "These spans specify the requirements check, the limits of delegation evidence and the corroborating signal relevant to order-specific approval."
    }
  },
  "stated_empirical_relation": {
    "component_id": "C006.stated_empirical_relation",
    "value": "NOT_APPLICABLE",
    "scope": "NOT_APPLICABLE",
    "provenance": {
      "refs": [],
      "support_status": "SUFFICIENT",
      "rationale": "The claim is supported without an unresolved empirical bridging relation."
    }
  },
  "rationale": "Availability of a delegation form establishes neither its applicability nor approval of the particular order. The prescribed checks therefore license withholding an assumption of rule satisfaction. The claim does not assert that such forms can never satisfy the rule.",
  "uncertainty": "Whether any particular form satisfies the rule remains case-specific; that uncertainty is consistent with the bounded claim.",
  "anomalies": []
}
